    N_('c. 900 BC'),
    N_('Metropolitan Museum (acc. 1934); findspot unrecorded'),
    N_('A simple wheel-made saucer with one edge pinched into a spout to hold the wick: the lamp that lit every Israelite house, burning a little olive oil through the night. Plain and everywhere, it is the lamp of the Psalmist\'s \'lamp unto my feet, and a light unto my path.\''),
